.list-cards-title {
  text-align: center;
  margin-bottom: 1.5rem;
}
.list-cards {
  --list-cards-object-fit: contain;
  --list-card-width: 270px;
  --list-card-border-color: #808080;
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(var(--list-card-width), 1fr));
  gap: 1.5rem;
}
@media (min-width: 993px) {
  .list-cards {
    gap: 2rem;
  }
}
.list-card {
  position: relative;
}
